function refreshSelection(){for(const [id,g] of meshes)for(const child of g.children)if(child.userData.selection)child.visible=id===selected;if(gizmo){scene.remove(gizmo);dispose(gizmo);gizmo=null;}const o=state.objects.find(o=>o.id===selected);$('gizmo-hint').hidden=!o||phase==='existing';if(o&&scene&&phase!=='existing'&&view!=='walk'){gizmo=new T.Group();for(const [axis,dir,color] of [['x',new T.Vector3(1,0,0),0xc9684d],['z',new T.Vector3(0,0,1),0x567fab]]){const arrow=new T.ArrowHelper(dir,new T.Vector3(o.x,.12,o.z),1,color,.18,.11);arrow.setColor(color);arrow.userData.gizmoAxis=axis;arrow.traverse(child=>{if(child.material){child.material.depthTest=false;child.renderOrder=30;}});gizmo.add(arrow);}scene.add(gizmo);}drawNeeded=true;}
function updateCamera(){if(!camera)return;const r=state.room;if(view==='walk'){camera.position.copy(walkPosition);const look=new T.Vector3(Math.sin(walkYaw)*Math.cos(walkPitch),Math.sin(walkPitch),-Math.cos(walkYaw)*Math.cos(walkPitch));camera.lookAt(camera.position.clone().add(look));}else if(view==='top'){camera.position.set(0,distance*Math.max(1,1/camera.aspect),0.001);camera.lookAt(0,0,0);}else{const radius=distance*Math.max(1,1.2/camera.aspect);camera.position.set(focusPoint.x+Math.sin(yaw)*Math.cos(elevation)*radius,Math.sin(elevation)*radius,focusPoint.z+Math.cos(yaw)*Math.cos(elevation)*radius);camera.lookAt(focusPoint.x,focusPoint.y,focusPoint.z);}roomGroup?.traverse(o=>{if(o.userData.overhead)o.visible=view==='walk';});camera.updateMatrixWorld();drawNeeded=true;}
function setView(next){if(next==='walk'&&phase!=='proposed')setPhase('proposed');view=next;if(next!=='walk'){focusPoint={x:0,y:.35,z:0};distance=Math.max(state.room.w,state.room.d,state.eps.height*1.6)*1.8;}placing=null;select(null);if(next==='walk'){walkPosition=new T.Vector3(0,1.65,state.room.d/2-.35);walkYaw=0;walkPitch=0;if(!state.flags.walked)change(p=>p.flags.walked=true,'Walkthrough unlocked. Use W A S D or the on-screen arrows.');}document.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===next)));$('walk-pad').hidden=next!=='walk';$('scene-help').textContent=next==='walk'?'Drag to look · W A S D / arrow keys to move':next==='top'?'Floor plan · Click an item to move it':'Drag the background to orbit · Scroll to zoom';updateCamera();if(next==='walk')canvas.focus({preventScroll:true});}
