const held=new Set();window.addEventListener('keydown',event=>{if(/INPUT|SELECT|TEXTAREA/.test(event.target.tagName))return;const key=event.key.toLowerCase();if(key==='escape'){placing=null;if(ghost){objectGroup.remove(ghost);dispose(ghost);ghost=null;}sync();return;}if((event.ctrlKey||event.metaKey)&&key==='z'){event.preventDefault();$(event.shiftKey?'undo-redo':'undo').click();return;}if(event.target===canvas){if(view==='walk'&&['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(key)){event.preventDefault();held.add(key);}else if(key==='r'){event.preventDefault();rotate();}else if(key==='d'&&!event.ctrlKey&&!event.metaKey&&view!=='walk'){event.preventDefault();$('duplicate').click();}else if(key==='delete'||key==='backspace'){event.preventDefault();remove();}else if(key==='enter'&&placing){event.preventDefault();$('auto-place').click();}else if(selected&&['arrowup','arrowdown','arrowleft','arrowright'].includes(key)){event.preventDefault();const o=state.objects.find(o=>o.id===selected);moveSelected(o.x+(key==='arrowright'?.25:key==='arrowleft'?-.25:0),o.z+(key==='arrowdown'?.25:key==='arrowup'?-.25:0));}}});window.addEventListener('keyup',event=>held.delete(event.key.toLowerCase()));window.addEventListener('blur',()=>{held.clear();endDrag(true);});document.addEventListener('visibilitychange',()=>{held.clear();lastFrame=0;});
