function blocked(x,z){const t=state.eps.thickness/100;if(x< -state.room.w/2+(state.eps.left?t:0)+.2||x>state.room.w/2-.2||z< -state.room.d/2+(state.eps.rear?t:0)+.2||z>state.room.d/2-.2)return true;return state.objects.some(o=>{if(o.type==='rug')return false;const f=footprint(o),localX=Math.cos(f.a)*(x-o.x)-Math.sin(f.a)*(z-o.z),localZ=Math.sin(f.a)*(x-o.x)+Math.cos(f.a)*(z-o.z);if(Math.abs(localX)>=f.w/2+.15||Math.abs(localZ)>=f.d/2+.15)return false;if(o.type==='epswall'&&EPS.wall(o,state.eps).holes.some(h=>h.y===0&&Math.abs(localX-h.x)<h.w/2-.15))return false;return true;});}
function walkStep(direction,amount){if(view!=='walk'||!walkPosition)return;let angle=walkYaw;if(direction==='back')angle+=Math.PI;if(direction==='left')angle-=Math.PI/2;if(direction==='right')angle+=Math.PI/2;const steps=Math.max(1,Math.ceil(amount/.05));for(let i=0;i<steps;i++){const x=walkPosition.x+Math.sin(angle)*amount/steps,z=walkPosition.z-Math.cos(angle)*amount/steps;if(!blocked(x,z)){walkPosition.x=x;walkPosition.z=z;}else break;}updateCamera();}
function frame(time){requestAnimationFrame(frame);const delta=lastFrame?Math.min((time-lastFrame)/1000,.25):0;lastFrame=time;if(document.hidden)return;if(view==='walk'){for(const [keys,direction] of [[['w','arrowup','forward'],'forward'],[['s','arrowdown','back'],'back'],[['a','arrowleft','left'],'left'],[['d','arrowright','right'],'right']])if(keys.some(k=>held.has(k)))walkStep(direction,delta*2);}if(drawNeeded){renderer.render(scene,camera);drawNeeded=false;}}
canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();$('webgl-error').hidden=false;announce('3D context lost. Reload to restore your autosaved plan.');});

const precise=n=>Number(n.toFixed(6)).toString();
function syncEPS(){const e=state.eps,q=EPS.estimate(state);document.querySelectorAll('[data-thickness]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.thickness===e.thickness)));$('asset-height').value=e.height;$('line-rear').checked=e.rear;$('line-left').checked=e.left;$('rear-openings').value=e.rearOpenings;$('left-openings').value=e.leftOpenings;$('rear-openings').disabled=!e.rear;$('left-openings').disabled=!e.left;$('waste-percent').value=e.waste;$('eps-volume').textContent=precise(q.volume);$('mobile-eps-volume').textContent=precise(q.volume)+' m³';$('mobile-eps-supply').textContent=precise(q.supplyVolume)+' m³';$('scene-eps').textContent=precise(q.volume)+' m³ EPS';$('eps-gross').textContent=precise(q.grossArea)+' m²';$('eps-openings').textContent=precise(q.openingArea)+' m²';$('eps-area').textContent=precise(q.netArea)+' m²';$('eps-extra').textContent=precise(q.wasteVolume)+' m³ / '+e.waste+'%';$('eps-supply').textContent=precise(q.supplyVolume)+' m³ ('+e.waste+'%)';$('eps-groups').replaceChildren(...q.groups.map(g=>{const row=document.createElement('p');row.textContent=g.thickness+' cm core · '+precise(g.netArea)+' m² · '+precise(g.volume)+' m³';return row;}));if(!q.groups.length)$('eps-groups').textContent='Add an EPS partition or select retained-wall lining.';syncSurfaceEquations(q);document.querySelectorAll('[data-light]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.light===state.light)));}
function syncEPSSelection(active){$('precise-rotation').hidden=active?.type!=='epswall';$('scene-turn').hidden=active?.type!=='epswall'||phase==='existing'||view==='walk';if(active?.type==='epswall'){$('wall-angle').value=degrees(active);$('scene-angle').textContent=degrees(active)+'°';}$('eps-wall-controls').hidden=active?.type!=='epswall';if(active?.type==='epswall'){$('wall-length').value=active.length;$('wall-height').value=active.height;$('wall-thickness').value=active.thickness;$('wall-opening').value=active.opening;for(const k of ['doorWidth','doorHeight','windowWidth','windowHeight','windowSill'])$('edit-'+k).value=active[k]??EPS.wall(active,state.eps)[k];}}
