$('apply-eps').addEventListener('click',()=>change(p=>{p.eps={...p.eps,height:Number($('asset-height').value),rear:$('line-rear').checked,left:$('line-left').checked,rearOpenings:Number($('rear-openings').value),leftOpenings:Number($('left-openings').value),waste:Number($('waste-percent').value)};},'EPS scope updated. The estimate uses net geometry, including opening and corner deductions.'));
$('apply-wall').addEventListener('click',()=>{if(!selected)return;change(p=>{const o=p.objects.find(o=>o.id===selected);if(o.type!=='epswall')return;Object.assign(o,{length:Number($('wall-length').value),height:Number($('wall-height').value),thickness:Number($('wall-thickness').value),opening:$('wall-opening').value,...Object.fromEntries(['doorWidth','doorHeight','windowWidth','windowHeight','windowSill'].map(k=>[k,Number($('edit-'+k).value)]))});},'EPS wall details applied. Opening geometry and core volume updated.');});
$('undo-redo').addEventListener('click',()=>{if(!future.length)return;history.push(copy(state));state=future.pop();selected=null;placing=null;save();rebuild();sync();announce('Change redone.');});
let epsClipboard=null;
function pasteGuide(original){if(!original){announce('Copy an element first.');return;}if(state.objects.length>=40){announce('This room has reached the 40-element limit.');return;}const candidates=[];for(let dx=-state.room.w;dx<=state.room.w;dx+=.25)for(let dz=-state.room.d;dz<=state.room.d;dz+=.25)if(dx||dz)candidates.push({dx,dz});candidates.sort((a,b)=>a.dx*a.dx+a.dz*a.dz-b.dx*b.dx-b.dz*b.dz);const nextObject={...copy(original),id:uid()},free=candidates.find(({dx,dz})=>!placementError({...nextObject,x:original.x+dx,z:original.z+dz}));if(!free){announce('No clear space fits this copy. Enlarge the room or move an element.');return;}nextObject.x=snap(original.x+free.dx);nextObject.z=snap(original.z+free.dz);if(phase==='existing')setPhase('proposed');if(view==='walk')setView('iso');if(change(p=>p.objects.push(nextObject),'Element pasted. Dimensions, rotation, thickness and openings retained.'))select(nextObject.id);}
function copyGuide(){const original=state.objects.find(o=>o.id===selected);if(!original){announce('Select an element to copy.');return;}epsClipboard=copy(original);announce('Element copied. Paste creates an independent measured copy.');}
$('duplicate').addEventListener('click',()=>{const original=state.objects.find(o=>o.id===selected);if(!original){announce('Select an element to duplicate.');return;}pasteGuide(original);});
const guideTools=document.createElement('div');guideTools.className='guide-edit-tools';guideTools.innerHTML='<button type="button" id="guide-copy">Copy</button><button type="button" id="guide-paste">Paste</button><span>Ctrl / ⌘ C · V · D</span>';document.querySelector('.view-toolbar').after(guideTools);
$('guide-copy').onclick=copyGuide;$('guide-paste').onclick=()=>pasteGuide(epsClipboard);
const resizeTools=document.createElement('div');resizeTools.className='guide-resize-tools';resizeTools.innerHTML='<p>Resize the selected EPS panel</p><div><button type="button" data-guide-size="length:-0.1">Shorten −10 cm</button><button type="button" data-guide-size="length:0.1">Lengthen +10 cm</button><button type="button" data-guide-size="height:-0.1">Lower −10 cm</button><button type="button" data-guide-size="height:0.1">Taller +10 cm</button></div>'; $('eps-wall-controls').prepend(resizeTools);
for(const b of resizeTools.querySelectorAll('button'))b.onclick=()=>{const [key,delta]=b.dataset.guideSize.split(':');change(p=>{const wall=p.objects.find(o=>o.id===selected);if(wall?.type==='epswall')wall[key]=+(wall[key]+Number(delta)).toFixed(5);},'EPS panel resized. Openings and core quantity recalculated.');};
window.addEventListener('keydown',e=>{if(document.getElementById('assembly-dialog')?.open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.target.isContentEditable||!(e.ctrlKey||e.metaKey))return;const key=e.key.toLowerCase();if(['c','v','d'].includes(key)){e.preventDefault();if(key==='c')copyGuide();if(key==='v')pasteGuide(epsClipboard);if(key==='d')$('duplicate').click();}});
$('focus-item').addEventListener('click',()=>{const o=state.objects.find(o=>o.id===selected);if(!o)return;const id=selected;setView('iso');select(id);focusPoint={x:o.x,y:o.type==='epswall'?o.height/2:.5,z:o.z};distance=o.type==='epswall'?6:5;updateCamera();});
function setPhase(value){phase=value;if(view==='walk')setView('iso');select(null);document.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.phase===value)));rebuild();syncDesign();announce(value==='existing'?'Existing asset view. Your proposed plan is retained.':value==='eps'?'EPS cutaway shows core thickness and openings. Quantities exclude finishes.':'Proposed design view.');}
for(const b of document.querySelectorAll('[data-phase]'))b.addEventListener('click',()=>setPhase(b.dataset.phase));
for(const b of document.querySelectorAll('[data-light]'))b.addEventListener('click',()=>change(p=>p.light=b.dataset.light,'Lighting mood updated.'));
$('capture').addEventListener('click',()=>{if(!renderer){announce('3D is unavailable.');return;}renderer.render(scene,camera);canvas.toBlob(blob=>{if(!blob){announce('This browser could not capture the view.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='greenshift-asset-concept.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Current concept view captured.');},'image/png');});
$('render-quality').addEventListener('change',()=>{if(!renderer)return;const detailed=$('render-quality').value==='studio';renderer.setPixelRatio(Math.min(devicePixelRatio||1,detailed?1.5:softwareRenderer?.75:1));keyLight.shadow.mapSize.set(detailed?2048:512,detailed?2048:512);keyLight.shadow.map?.dispose();keyLight.shadow.map=null;renderer.shadowMap.needsUpdate=true;const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);drawNeeded=true;announce(detailed?'Studio rendering: detailed shadows and higher pixel density.':'Performance rendering: reduced shadow resolution and pixel density.');});
$('export-eps').addEventListener('click',()=>{const q=EPS.estimate(state),rows=[['Surface','Length (m)','Height (m)','Gross area (m²)','Openings (m²)','Net area (m²)','EPS thickness (cm)','Installed core (m³)','Allowance (%)','Supply core (m³)','Scope note']];for(const surface of q.surfaces)rows.push([surface.kind,surface.length,surface.height,surface.grossArea,surface.openingArea,surface.netArea,surface.thickness,surface.volume,q.wastePercent,surface.volume*(1+q.wastePercent/100),'']);rows.push(['TOTAL','','',q.grossArea,q.openingArea,q.netArea,q.groups.length>1?'mixed':q.groups[0]?.thickness||state.eps.thickness,q.volume,q.wastePercent,q.supplyVolume,'EPS core only. Skins, finishes and structure excluded. Confirm in measured design review.']);const csv=rows.map(row=>row.map(value=>'"'+String(typeof value==='number'?Number(value.toFixed(6)):value).replaceAll('"','""')+'"').join(',')).join('\r\n');download('greenshift-eps-takeoff.csv','\uFEFF'+csv,'text/csv;charset=utf-8');announce('EPS core takeoff downloaded.');});

function syncSurfaceEquations(q){$('eps-surface-count').textContent=q.surfaces.length+' measured EPS surface'+(q.surfaces.length===1?'':'s');$('eps-surfaces').replaceChildren(...q.surfaces.map((s,i)=>{const article=document.createElement('article'),label=s.kind==='partition'?'Partition '+(state.objects.filter(o=>o.type==='epswall').findIndex(o=>o.id===s.id)+1):s.kind==='rear'?'Rear wall lining':'Left wall lining';const h=document.createElement('b');h.textContent=label+' · '+s.thickness+' cm';const equation=document.createElement('p');equation.textContent='('+precise(s.length)+' × '+precise(s.height)+' − '+precise(s.openingArea)+') m² × '+precise(s.thickness/100)+' m';for(const hole of s.holes){const opening=document.createElement('p');opening.textContent='Opening: '+precise(hole.w)+' × '+precise(hole.h)+' m = '+precise(hole.w*hole.h)+' m²';article.append(opening);}const result=document.createElement('strong');result.textContent='= '+precise(s.volume)+' m³ EPS';article.prepend(h);article.append(equation,result);if(s.id){const b=document.createElement('button');b.textContent='Edit / rotate wall';b.addEventListener('click',()=>{if(phase==='existing')setPhase('proposed');select(s.id);$('selection-controls').scrollIntoView({block:'nearest',behavior:'smooth'});});article.append(b);}return article;}));if(!q.surfaces.length)$('eps-surfaces').textContent='No EPS counted yet. Add a measured wall to begin.';$('eps-corner-note').textContent=q.cornerDeduction?'Corner overlap removed once: '+precise(q.cornerDeduction)+' m². Rear lining length is shortened by '+precise(state.eps.thickness/100)+' m.':'Only the surfaces listed above are included. Glazing, panels, portals and ceiling rafts are excluded from EPS core quantities.';}
$('jump-eps').addEventListener('click',()=>{$('measure-card').scrollIntoView({block:'start',behavior:'smooth'});$('new-wall-length').focus({preventScroll:true});});
function turnPartition(delta,absolute){const o=state.objects.find(o=>o.id===selected);if(o?.type!=='epswall')return;const angle=absolute??((degrees(o)+delta)%360+360)%360;if(!Number.isFinite(angle)||angle<0||angle>=360){announce('Enter an angle from 0 to 359 degrees.');return;}change(p=>{const wall=p.objects.find(x=>x.id===selected);wall.angle=angle;wall.rot=Math.floor(angle/90)%4;},'EPS partition turned to '+angle+'°. Its measured volume is unchanged.');}
$('apply-angle').addEventListener('click',()=>turnPartition(0,Number($('wall-angle').value)));
for(const [id,amount] of [['turn-left',-15],['turn-right',15],['scene-turn-left',-15],['scene-turn-right',15]])$(id).addEventListener('click',()=>turnPartition(amount));
$('add-measured-wall').addEventListener('click',()=>{const o={...item('epswall',0,0),length:Number($('new-wall-length').value),height:Number($('new-wall-height').value),opening:$('new-wall-opening').value,...Object.fromEntries(['doorWidth','doorHeight','windowWidth','windowHeight','windowSill'].map(k=>[k,Number($('new-'+k).value)]))};try{EPS.wall(o,state.eps);}catch(e){announce(e.message);return;}const points=[];for(let x=-state.room.w/2+.25;x<state.room.w/2;x+=.25)for(let z=-state.room.d/2+.25;z<state.room.d/2;z+=.25)points.push({x,z});points.sort((a,b)=>a.x*a.x+a.z*a.z-b.x*b.x-b.z*b.z);let candidate;for(const rot of [0,1]){candidate=points.map(p=>({...o,...p,rot})).find(p=>!placementError(p));if(candidate)break;}if(!candidate){announce('No clear space fits that measured wall. Move the architectural elements, enlarge the room, or start with a blank canvas.');return;}if(change(p=>p.objects.push(candidate),'Measured EPS wall added. Select its angle or drag the floor arrows.')){setPhase('proposed');select(candidate.id);}});

function designPalette(){return globalThis.GreenShiftDesign.styles[state.designStyle]||globalThis.GreenShiftDesign.styles.contemporary;}
function fitoutSchedule(){const q=EPS.estimate(state),liningOpenings=q.surfaces.filter(s=>s.kind!=='partition').reduce((n,s)=>n+s.openingArea,0),partitionFaces=2*q.surfaces.filter(s=>s.kind==='partition').reduce((n,s)=>n+s.netArea,0);return {style:designPalette().name,floorFinish:floorNames[state.floor],floorArea:state.room.w*state.room.d,ceilingRaftArea:state.fitout.lighting?Math.min(state.room.w-1,3.4)*Math.min(state.room.d-1,2):0,visibleRetainedWallArea:(state.room.w+state.room.d)*state.eps.height-liningOpenings,partitionFinishFaces:partitionFaces,epsCore:q.volume,epsSupply:q.supplyVolume,featureWall:state.fitout.featureWall?'Included / concept':'Not selected',ceilingLighting:state.fitout.lighting?'Included / concept':'Not selected',architecturalElements:state.objects.filter(o=>!['epswall','partition'].includes(o.type)).length};}
function syncDesign(){const D=globalThis.GreenShiftDesign;if(!D)return;document.querySelectorAll('[data-style]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.style===state.designStyle)));document.querySelectorAll('[data-build-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.buildStage===phase)));$('style-description').textContent=designPalette().caption;$('interior-style-name').textContent=designPalette().name;$('feature-wall').checked=state.fitout.featureWall;$('ceiling-lighting').checked=state.fitout.lighting;$('stage-description').textContent=D.stages.find(s=>s[0]===phase)?.[2]||'';const q=fitoutSchedule(),rows=[['Floor finish / '+q.floorFinish,precise(q.floorArea)+' m²'],['Visible retained walls',precise(q.visibleRetainedWallArea)+' m²'],['EPS partition finish / both faces',precise(q.partitionFinishFaces)+' m²'],['Ceiling raft / lighting',precise(q.ceilingRaftArea)+' m²'],['Architectural elements / concept',q.architecturalElements+' pcs']];$('interior-schedule').replaceChildren(...rows.map(([label,value])=>{const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);return row;}));}
function buildFitout(group){if(!renderer)return;const p=designPalette(),{w,d}=state.room,H=state.eps.height,t=state.eps.thickness/100,rear=-d/2+(state.eps.rear?t:0)+.04;
 if(phase==='services'){for(const [x,color] of [[-.35,0x5c90a4],[.35,0xc58058]]){for(const [a,b] of [[new T.Vector3(x,H-.18,rear),new T.Vector3(x,H-.18,d/2-.5)],[new T.Vector3(x,.2,rear),new T.Vector3(x,H-.18,rear)]]){const dir=new T.Vector3().subVectors(b,a),pipe=new T.Mesh(new T.CylinderGeometry(.025,.025,dir.length(),8),mat(color));pipe.position.copy(a).add(b).multiplyScalar(.5);pipe.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),dir.normalize());group.add(pipe);}}}
 if(!['proposed','finishes'].includes(phase))return;
 if(state.fitout.featureWall){if(p.feature==='slats'){for(let x=-w*.33;x<w*.33;x+=.13)box(group,.055,H*.7,.045,x,H*.5,rear+.03,p.wood);}else if(p.feature==='niche'){const shape=new T.Shape(),R=Math.min(w*.18,.85),base=H*.18;shape.moveTo(-R,base);shape.lineTo(R,base);shape.lineTo(R,base+1.1);shape.absarc(0,base+1.1,R,0,Math.PI,false);shape.closePath();const niche=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:.035,bevelEnabled:false}),mat(0xe3d4bc));niche.position.z=rear;group.add(niche);box(group,R*1.8,.055,.16,0,base+.45,rear+.1,p.wood);}else{for(const x of [-.7,.7]){box(group,1.08,.88,.04,x,H*.62,rear+.03,p.metal);box(group,.96,.76,.012,x,H*.62,rear+.058,p.art);const art=new T.Mesh(new T.CircleGeometry(.22,32),mat(p.accent));art.position.set(x+.08,H*.62,rear+.07);group.add(art);}}}
 if(state.fitout.lighting&&phase==='proposed'){const raft=box(group,Math.min(w-1,3.4),.07,Math.min(d-1,2),0,H-.16,0,state.designStyle==='industrial'?p.metal:0xe9e6d9);raft.userData.overhead=true;raft.visible=view==='walk';for(const x of [-.8,.8]){const drop=H<2.7?.12:.47,wire=new T.Mesh(new T.CylinderGeometry(.012,.012,Math.max(.02,drop-.1),8),mat(p.metal));wire.position.set(x,H-drop/2,0);group.add(wire);const shade=new T.Mesh(new T.ConeGeometry(state.designStyle==='japandi'?.3:.23,.22,32,1,true),mat(p.wood));shade.position.set(x,H-drop,0);shade.rotation.x=Math.PI;group.add(shade);const bulb=new T.Mesh(new T.SphereGeometry(.065,12,8),new T.MeshStandardMaterial({color:0xffefce,emissive:0xffd29c,emissiveIntensity:1.5}));bulb.position.set(x,H-drop-.07,0);group.add(bulb);}const glow=new T.PointLight(0xffe1b1,1,6,2);glow.position.set(0,H-.8,0);group.add(glow);}
}
const designs=globalThis.GreenShiftDesign;
if(designs){for(const [key,style] of Object.entries(designs.styles)){const b=document.createElement('button');b.dataset.style=key;const image=document.createElement('img');image.src='./interior-style-'+key+'.png?v=journey2';image.alt='';image.width=160;image.height=110;b.append(image,document.createTextNode(style.name));b.onclick=()=>change(p=>{p.designStyle=key;p.floor=style.floor;p.wall=style.wall;p.light=style.light;p.fitout={featureWall:true,lighting:true};p.flags.customized=true;},style.name+' interior specification applied. Your measured layout is retained.');$('design-styles').append(b);}for(const [stage,label] of designs.stages){const b=document.createElement('button');b.dataset.buildStage=stage;b.textContent=label;b.onclick=()=>{setPhase(stage);syncDesign();};$('build-steps').append(b);}}
