$('export-build').onclick=()=>{const q=fitoutSchedule(),csv=[['Item','Concept quantity'],...Object.entries(q)].map(row=>row.map(v=>'"'+String(typeof v==='number'?precise(v):v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('greenshift-interior-finish-schedule.csv','\uFEFF'+csv,'text/csv;charset=utf-8');announce('Interior finish schedule downloaded. Quantities cover the visible model.');};

